For a prime $v$ of $F$, define
\begin{equation*}
\mathcal{H}_v^\bullet:=\mathrm{Ext}^\bullet_{C_{\rm c}(\mathbf{G}(F_v),R)}(R[\mathbf{G}(F_v)/K_v],R[\mathbf{G}(F_v)/K_v]),
\end{equation*}
where $C_{\rm c}(\mathbf{G}(F_v),R)$ is the ring of compactly supported locally constant $R$-valued functions on $\mathbf{G}(F_v)$.

\label{conj:pv:finite}
For all but finitely many $p$,
the map $\Psi^\bullet$ in \eqref{eq:psi} is an isomorphism of graded $\mathbb{T}^\bullet$-modules.

\label{thm:A}
If $p$ does not divide the order of $\mathcal{O}_F^\times/E(\mathfrak{N})$, 
then $\Psi^\bullet$ is an isomorphism of $\mathbb{T}^\bullet$-modules.

\label{property:torus}
The space $E(\mathfrak{N})\backslash F_{\mathbb{R},+}^\times/U$ 
is a model for the classifying space of $E(\mathfrak{N})$.

\label{representative:choice} 
The image of $\iota_a$ is independent of the choice of a representative of a ray class 
$[a]\in\mathrm{Cl}_F^+(\mathfrak{N})$.

\label{derived:hecke:operator:definition}
For $\alpha\in H^\bullet(O_v^\times,R)$, 
let us define $h_{1,\alpha}\in\mathrm{End}_RH^\bullet(Y(\mathfrak{N}),R)$ by
\begin{equation*}
h_{1,\alpha}c:=\langle\alpha\rangle\cup c\quad\text{for}\quad c\in H^\bullet(Y(\mathfrak{N}),R),
\end{equation*} 
where $\cup$ is the cup product on the graded $R$-algebra $H^\bullet(Y(\mathfrak{N}),R)$. 
$h_{1,\alpha}$ is called {\it derived Hecke operator}.

\label{computation:hecke:operator}  
Let $\alpha\in H^\bullet(O_v^\times,R)$. Then,
\begin{equation*}
\iota_a^*(h_{1,\alpha}c)=i_{v,\mathfrak{N}}^*(\alpha)\cup\iota_{a}^*(c)
\quad \text{for}\quad c\in H^\bullet(Y(\mathfrak{N}),R).
\end{equation*}

We give a brief proof; see \cite[Proposition 3.4]{KimKwon2024} for details.
The classifying maps give the following homotopy-commutative diagram:
\begin{equation}\label{cohomology:commutative:diagram}
\begin{tikzcd}
E(\mathfrak{N})\backslash F_{\mathbb{R},+}^\times/U
\arrow{r}{=}\arrow{d}{\simeq}
&E(\mathfrak{N})\backslash F_{\mathbb{R},+}^\times/U
\arrow{r}{\iota_a}\arrow{d}{\psi_{v,\mathfrak{N}}}
&Y(\mathfrak{N})\arrow{d}{\phi_{v,\mathfrak{N}}}\\
\mathcal{B}E(\mathfrak{N})\arrow{r}
&\mathcal{B}\frac{E(\mathfrak{N})}{E(v\mathfrak{N})}\arrow{r}{\mathcal{B}i_{v,\mathfrak{N}}}
&\mathcal{B}\kappa_v^\times.
\end{tikzcd}
\end{equation}
The bottom left arrow is induced by the canonical projection.
Each square follows from the map of bundles.
By Proposition~\ref{property:torus}, we identify the cohomology of
$E(\mathfrak{N})\backslash F_{\mathbb{R},+}^\times/U$ with $H^\bullet(E(\mathfrak{N}),R)$.
Applying $H^\bullet(-,R)$ to the diagram~\eqref{cohomology:commutative:diagram}, we obtain that
$\iota_a^*(\langle\alpha\rangle)=i_{v,\mathfrak{N}}^*(\alpha)$ under the identification.
Then, we are done since $\iota_a^*$ is a map of cohomology rings.

\label{computation:hecke:operator:product}
Let $\underline{\alpha}$ be as above.
Then,
\begin{equation*}
\iota_a^*(h_{1,\underline{\alpha}}c)=I_{\mathfrak{N}}(\underline{\alpha})\cup\iota_{a}^*(c)
\quad \text{for} \quad c\in H^\bullet(Y(\mathfrak{N}),R).
\end{equation*}

\label{modp:nonvanishing}
The dimension $t_p$ is equal to $r_p-\delta_p$. 
In particular, the map $\Psi^\bullet$ is an isomorphism if and only if $\delta_p=r_p-r$.

\label{cor:4.10}
Let $\mathfrak{m}$ be a maximal ideal of $\mathbb{T}^0$. If $p$ does not divide $|\mathcal{O}_F^\times/E(\mathfrak{N})|$, we have the following isomorphism:
\begin{equation*}
\mathbb{T}^\bullet_\mathfrak{m}\otimes_{\mathbb{T}^0_\mathfrak{m}}H^0(Y(\mathfrak{N}),\mathbb{F}_p)_\mathfrak{m}
\cong H^\bullet(Y(\mathfrak{N}),\mathbb{F}_p)_\mathfrak{m}.
\end{equation*}
